package com.feynman.backend;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;

/**
 * Entry point for the Feynman learning-platform backend.
 *
 * <p>The backend evaluates a user's notebooks/pages and scores how well the
 * topic appears to be understood, following the Feynman technique (if you can
 * explain it simply, you understand it). Scores replace the front-end's
 * hard-coded {@code progress.ts} placeholder values.</p>
 */
@SpringBootApplication
@ConfigurationPropertiesScan
public class FeynmanBackendApplication {

    public static void main(String[] args) {
        SpringApplication.run(FeynmanBackendApplication.class, args);
    }
}

package com.feynman.backend.controller;

import com.feynman.backend.service.OpenAiEvaluationService.EvaluationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Translates uncaught exceptions into RFC 7807 {@link ProblemDetail} responses.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setTitle("Invalid request");
        pd.setDetail(ex.getBindingResult().getAllErrors().stream()
                .findFirst()
                .map(err -> err.getDefaultMessage())
                .orElse("Validation failed"));
        return pd;
    }

    @ExceptionHandler(EvaluationException.class)
    public ProblemDetail handleEvaluation(EvaluationException ex) {
        log.error("Evaluation failed", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_GATEWAY);
        pd.setTitle("Evaluation failed");
        pd.setDetail(ex.getMessage());
        return pd;
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail handleGeneric(Exception ex) {
        log.error("Unexpected error", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR);
        pd.setTitle("Internal error");
        pd.setDetail("An unexpected error occurred.");
        return pd;
    }
}

package com.feynman.backend.dto;

import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Request payload for {@code POST /api/evaluate}.
 *
 * <p>The frontend sends its full set of notebooks and pages; the backend
 * returns an understanding score (0–100) for every page and an aggregate
 * score for every notebook. When {@code notebookId} is provided, only that
 * notebook (and its pages) is evaluated.</p>
 *
 * @param notebookId Optional filter — evaluate only this notebook when set.
 */
public record EvaluateRequest(
        @NotNull List<NotebookDto> notebooks,
        @NotNull List<PageDto> pages,
        String notebookId
) {
}

package com.feynman.backend.dto;

import java.util.Map;

/**
 * Response payload for {@code POST /api/evaluate}.
 *
 * <p>Scores are split so the frontend can merge page- and notebook-level
 * results independently, matching the shape consumed by {@code setLiveScores}.
 * Each map is keyed by the entity id (matching the frontend seed ids).</p>
 */
public record EvaluationResponse(
        Map<String, ScoreDto> pageScores,
        Map<String, ScoreDto> notebookScores
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code Notebook} type.
 */
public record NotebookDto(
        String id,
        String title,
        String color
) {
}

package com.feynman.backend.dto;

import java.util.List;

/**
 * Mirrors the frontend {@code Page} type. Represents a single page whose
 * understanding we want to score.
 */
public record PageDto(
        String id,
        String notebookId,
        String parentId,
        String title,
        String content,
        List<TextBoxDto> boxes,
        Integer order
) {
    /** Combined free text of the page (content + all text boxes). */
    public String combinedText() {
        StringBuilder sb = new StringBuilder();
        if (content != null) {
            sb.append(content);
        }
        if (boxes != null) {
            for (TextBoxDto box : boxes) {
                if (box != null && box.text() != null && !box.text().isBlank()) {
                    sb.append("\n").append(box.text());
                }
            }
        }
        return sb.toString().trim();
    }
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code TextBox} type: a free-floating text box on the
 * page canvas. Only {@code text} matters for evaluation.
 */
public record TextBoxDto(
        String id,
        Double x,
        Double y,
        String text,
        Double width
) {
}

import type { Notebook, Page } from '@/types'
import { evaluateNotes } from '@/services/evaluationApi'
import type { EvaluationResult } from '@/services/evaluationApi'

/**
 * @deprecated Use `@/services/evaluationApi` directly.
 *
 * Kept as a thin re-export so any existing imports of `@/api/evaluation`
 * continue to resolve to the single canonical client.
 */
export type { Score, EvaluationResult } from '@/services/evaluationApi'
export { evaluateNotes } from '@/services/evaluationApi'

/** @deprecated Prefer `evaluateNotes(notebooks, pages, notebookId?)`. */
export async function evaluateNotebooks(payload: {
  notebooks: Notebook[]
  pages: Page[]
  notebookId?: string
}): Promise<EvaluationResult> {
  return evaluateNotes(payload.notebooks, payload.pages, payload.notebookId)
}

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import FormatMenu from '@/components/FormatMenu.vue'

// jsdom implements neither execCommand nor queryCommandState, so we stub them
// and assert against the spies. queryCommandState defaults to false unless a
// test overrides it (used for the active-state assertions below).
let execCommand: ReturnType<typeof vi.fn>
let queryCommandState: ReturnType<typeof vi.fn>

beforeEach(() => {
  execCommand = vi.fn().mockReturnValue(true)
  queryCommandState = vi.fn().mockReturnValue(false)
  // @ts-expect-error - not present in jsdom's Document typings
  document.execCommand = execCommand
  // @ts-expect-error - not present in jsdom's Document typings
  document.queryCommandState = queryCommandState
})

const props = { x: 100, y: 100 }

describe('FormatMenu', () => {
  describe('accessibility roles', () => {
    it('exposes a menu role with an accessible label', () => {
      const wrapper = mount(FormatMenu, { props })
      const menu = wrapper.get('[role="menu"]')
      expect(menu.attributes('aria-label')).toBe('Text formatting')
    })

    it('labels the inline-formatting group', () => {
      const wrapper = mount(FormatMenu, { props })
      const group = wrapper.get('[aria-label="Inline formatting"]')
      expect(group.attributes('role')).toBe('group')
    })

    it('marks list items with the menuitem role', () => {
      const wrapper = mount(FormatMenu, { props })
      expect(wrapper.findAll('[role="menuitem"]').length).toBeGreaterThan(0)
    })
  })

  describe('formatting commands', () => {
    it('runs the bold command and emits "applied" when Bold is clicked', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="Bold"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
      expect(wrapper.emitted('applied')).toBeTruthy()
    })

    it('forces CSS styling for colour commands', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No text colour"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('styleWithCSS', false, 'true')
      expect(execCommand).toHaveBeenCalledWith('foreColor', false, '#242424')
    })

    it('applies a highlight colour via hiliteColor', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No highlight"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('hiliteColor', false, 'transparent')
    })

    it('prompts for and normalises a link URL', async () => {
      const promptSpy = vi.spyOn(window, 'prompt').mockReturnValue('example.com')
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[title="Insert link (Ctrl+K)"]').trigger('click')
      expect(promptSpy).toHaveBeenCalled()
      expect(execCommand).toHaveBeenCalledWith('createLink', false, 'https://example.com')
    })
  })

  describe('active-state indicators', () => {
    it('reflects the current selection state via aria-pressed and .active', async () => {
      queryCommandState.mockImplementation((cmd: string) => cmd === 'bold')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      const bold = wrapper.get('[aria-label="Bold"]')
      expect(bold.attributes('aria-pressed')).toBe('true')
      expect(bold.classes()).toContain('active')

      const italic = wrapper.get('[aria-label="Italic"]')
      expect(italic.attributes('aria-pressed')).toBe('false')
      expect(italic.classes()).not.toContain('active')
    })
  })

  describe('keyboard shortcuts', () => {
    it('runs bold on Ctrl+B', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b', ctrlKey: true }))
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
    })

    it('runs strikethrough only with the Shift modifier on Ctrl+Shift+X', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'x', ctrlKey: true }))
      expect(execCommand).not.toHaveBeenCalledWith('strikeThrough', false, undefined)

      window.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'x', ctrlKey: true, shiftKey: true })
      )
      expect(execCommand).toHaveBeenCalledWith('strikeThrough', false, undefined)
    })

    it('emits "close" on Escape', () => {
      const wrapper = mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }))
      expect(wrapper.emitted('close')).toBeTruthy()
    })

    it('ignores shortcut keys without a modifier', () => {
      mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b' }))
      expect(execCommand).not.toHaveBeenCalledWith('bold', false, undefined)
    })
  })

  describe('selection preservation', () => {
    it('prevents default on mousedown so the selection is not stolen', async () => {
      const wrapper = mount(FormatMenu, { props })
      const event = new MouseEvent('mousedown', { cancelable: true, bubbles: true })
      wrapper.get('[role="menu"]').element.dispatchEvent(event)
      expect(event.defaultPrevented).toBe(true)
    })
  })

  describe('lifecycle', () => {
    it('stops listening for selection changes after unmount', async () => {
      const removeSpy = vi.spyOn(document, 'removeEventListener')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      wrapper.unmount()
      expect(removeSpy).toHaveBeenCalledWith('selectionchange', expect.any(Function))
    })
  })
})

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import FormatMenu from '@/components/FormatMenu.vue'

// jsdom implements neither execCommand nor queryCommandState, so we stub them
// and assert against the spies. queryCommandState defaults to false unless a
